from scipy.optimize import least_squares
one=np.ones_like(eps)
def mkA(p):
    E=eps*np.exp(-p[0]*eps/T)
    base=p[1]+p[2]*T+p[3]*T**2+p[4]*T**3+p[5]/T+p[6]*np.log(T)
    return base+p[7]*E/T
def mkB(p):
    E=eps*np.exp(-p[0]*eps)
    base=p[1]+p[2]*T+p[3]*T**2+p[4]*T**3+p[5]/T+p[6]*np.log(T)
    return base+p[7]*E/T**p[8]
for name,f,p0 in [('A',mkA,[0.756*3,15.8,-11.4,1.4,-0.056,4.4,14.8,31.4]),('B',mkB,[0.756,15.8,-11.4,1.4,-0.056,4.4,14.8,31.4,1.0])]:
    best=None
    for s in [1.0,0.5,2.0]:
        q=np.array(p0,float); q[0]=q[0]*s
        try:
            r=least_squares(lambda p: f(p)-sigma,q)
            nm=np.mean(r.fun**2)/np.var(sigma)
            if best is None or nm<best[0]: best=(nm,r.x)
        except Exception as e: print(e)
    print(name,best[0],np.round(best[1],5))
